-- PostgreSQL counterpart of sqlite/028_permissions_phase3.sql (Phase 3 permissions).


SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_ADMINISTRATOR' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.PAYREC.VIEW','ACC.PAYREC.ALLOCATE','PRJ.PROJECT.VIEW','PRJ.PROJECT.CREATE','PRJ.PROJECT.UPDATE','PRJ.PROJECT.DELETE','PRJ.TASK.MANAGE','AST.ASSET.VIEW','AST.ASSET.CREATE','AST.ASSET.UPDATE','AST.ASSET.DELETE') ON CONFLICT DO NOTHING;
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_USER' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.PAYREC.VIEW','ACC.PAYREC.ALLOCATE','PRJ.PROJECT.VIEW','PRJ.PROJECT.CREATE','PRJ.PROJECT.UPDATE','PRJ.TASK.MANAGE','AST.ASSET.VIEW','AST.ASSET.CREATE','AST.ASSET.UPDATE') ON CONFLICT DO NOTHING;
SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code = 'ROLE_VIEWER' AND r.is_active = true AND p.is_active = true AND p.permission_code IN ('ACC.PAYREC.VIEW','PRJ.PROJECT.VIEW','AST.ASSET.VIEW') ON CONFLICT DO NOTHING;
